import { PRESENCE_TTL_MS } from "@/data/presence";

// Visitor ids are generated by the browser; anything else is rejected.
const VISITOR_ID = /^[a-f0-9]{32}$/;
const MAX_VISITORS = 10_000;

// Last heartbeat per open tab. Kept in memory, so it only counts visitors of
// this server process and starts from zero after a restart.
const lastSeen = new Map<string, number>();

// Each open tab posts its id as a heartbeat and gets back the online count.
export async function POST(request: Request) {
  const id = await request.text();
  if (!VISITOR_ID.test(id)) return new Response(null, { status: 400 });

  const now = Date.now();
  for (const [visitor, seen] of lastSeen) {
    if (now - seen > PRESENCE_TTL_MS) lastSeen.delete(visitor);
  }
  if (lastSeen.has(id) || lastSeen.size < MAX_VISITORS) lastSeen.set(id, now);

  return Response.json({ online: lastSeen.size });
}
